import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ReentrantLock;
import java.util.stream.Stream;
import java.util.zip.CRC32;

public class Main {
    private static final ConcurrentHashMap<Path, ReentrantLock> FILE_LOCKS = new ConcurrentHashMap<>();

    public static final class FileResult {
        private final String path;
        private final long bytes;
        private final long lines;
        private final String checksum;
        private final String error;

        public FileResult(String path, long bytes, long lines, String checksum, String error) { ... }
        getters, toString.
    }

    public static FileResult processFile(String filePath) throws IOException { return processFile(Paths.get(filePath)); }

    public static FileResult processFile(Path filePath) throws IOException {
        Path normalized = filePath.toAbsolutePath().normalize();
        ReentrantLock lock = FILE_LOCKS.computeIfAbsent(normalized, k -> new ReentrantLock());
        lock.lock();
        try {
            return processFileWithoutExternalLock(normalized);
        } finally {
            lock.unlock();
        }
    }

    private static FileResult processFileWithoutExternalLock(Path normalized) throws IOException {
        CRC32 crc = new CRC32();
        long bytes = 0;
        long lines = 0;
        int lastByte = -1;
        try (InputStream in = Files.newInputStream(normalized)) {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = in.read(buffer)) != -1) {
                crc.update(buffer, 0, read);
                bytes += read;
                for (int i = 0; i < read; i++) {
                    if (buffer[i] == '\n') lines++;
                }
                lastByte = buffer[read - 1] & 0xFF;
            }
        }
        if (bytes > 0 && lastByte != '\n') lines++;
        return new FileResult(normalized.toString(), bytes, lines, Long.toHexString(crc.getValue()), null);
    }

    public static List<FileResult> processDirectory(String directoryPath, int threadCount) throws IOException {
       return processDirectory(Paths.get(directoryPath), threadCount);
    }

    public static List<FileResult> processDirectory(Path directoryPath, int threadCount) throws IOException {
       Path dir = directoryPath.toAbsolutePath().normalize();
       if (!Files.isDirectory(dir)) throw new IOException("Not a directory: " + dir);
       List<Path> files = new ArrayList<>();
       try (Stream<Path> stream = Files.walk(dir, FileVisitOption.FOLLOW_LINKS)) {
           stream.filter(Files::isRegularFile).forEach(files::add);
       }
       return processFiles(files, threadCount);
    }

    public static List<FileResult> processFiles(List<Path> filePaths, int threadCount) throws IOException {
       int workers = Math.max(1, threadCount);
       ExecutorService pool = Executors.newFixedThreadPool(workers);
       List<Future<FileResult>> futures = new ArrayList<>();
       for (Path filePath : filePaths) {
          final Path file = filePath.toAbsolutePath().normalize();
          futures.add(pool.submit(() -> processFile(file)));
       }
       pool.shutdown();
       List<FileResult> results = new ArrayList<>();
       for (Future<FileResult> future : futures) {
          try { results.add(future.get()); }
          catch (InterruptedException e) { Thread.currentThread().interrupt(); pool.shutdownNow(); throw new IOException("Interrupted", e); }
          catch (ExecutionException e) { Throwable cause = e.getCause(); if (cause instanceof IOException) throw (IOException) cause; throw new IOException("File processing failed", cause); }
       }
       return results;
    }

    public static List<FileResult> processFiles(String[] filePaths, int threadCount) throws IOException {
       List<Path> paths = new ArrayList<>(); for (String p : filePaths) paths.add(Paths.get(p)); return processFiles(paths, threadCount);
    }

    public static void main(String[] args) throws Exception {
       String directory = args.length > 0 ? args[0] : ".";
       int threadCount = args.length > 1 ? Integer.parseInt(args[1]) : Math.max(2, Runtime.getRuntime().availableProcessors());
       List<FileResult> results = processDirectory(directory, threadCount);
       for (FileResult result : results) System.out.println(result);
    }
}

